INSERT INTO `content_pages` VALUES (1,'dat-san','Đặt sân và giữ chỗ','faq','Chọn chi nhánh, ngày, khung giờ và sân trống. Kiểm tra tổng tiền trước khi xác nhận. Lịch đặt trực tuyến cần thanh toán phần đặt cọc trong thời hạn hiển thị. Lịch chưa đủ đặt cọc sẽ được tự giải phóng khi hết hạn.',1,'2026-10-11 10:43:33','2026-10-11 10:43:33'),(2,'huy-lich','Hủy lịch và hoàn tiền','faq','Bạn có thể tự hủy lịch chưa thanh toán trước giờ chơi. Lịch thanh toán hoàn toàn bằng ví có thể tự hủy và nhận lại tiền vào ví trước giờ chơi ít nhất 4 tiếng. Với các phương thức khác, gửi yêu cầu hỗ trợ hoặc liên hệ chi nhánh để đối soát và hoàn tiền.',1,'2026-10-11 10:43:33','2026-10-11 10:43:33'),(3,'diem-thuong','Tích điểm và quyền lợi hội viên','faq','Mỗi 10.000đ thanh toán cho buổi chơi đã hoàn tất hoặc mua hàng được tích 1 điểm. Đổi điểm thành tiền trong ví tại mục Quyền lợi. Hạng hội viên được xét theo tổng điểm đã tích; ưu đãi phù hợp được áp dụng khi tính giá sân.',1,'2026-10-11 10:43:33','2026-10-11 10:43:33'),(4,'cong-dong','Chơi cùng nhau, tôn trọng nhau','faq','Đăng bài tìm bạn chơi, tham gia nhóm và trò chuyện. Bài có ngôn từ cần kiểm tra sẽ chờ người quản trị duyệt. Bạn có thể báo cáo nội dung, chặn tài khoản và gỡ bài của mình. Không chia sẻ thông tin riêng của người khác.',1,'2026-10-11 10:43:33','2026-10-11 10:43:33'),(5,'ve-chung-toi','Kết nối sân chơi cầu lông','page','Badminton Hub giúp bạn tìm khung giờ phù hợp, đặt sân và kết nối người chơi. Xem thông tin từng chi nhánh trước khi lựa chọn; quản lý lịch, thanh toán và yêu cầu hỗ trợ trong tài khoản.',1,'2026-10-11 10:43:33','2026-10-11 10:43:33'),(6,'huong-dan-rally-1','Cách chọn giờ sân ít đông','faq','Mở Đặt sân, chọn chi nhánh và ngày chơi rồi xem các ô trống trong ma trận. So sánh khung giờ buổi sáng hoặc đầu giờ chiều; giá được hiển thị trước khi xác nhận.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(7,'huong-dan-rally-2','Chuẩn bị trước buổi chơi','faq','Kiểm tra ngày, giờ, chi nhánh và mã nhận sân trong Lịch của tôi. Mang giày phù hợp, vợt và nước uống; đến sớm để làm thủ tục tại quầy.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(8,'huong-dan-rally-3','Gửi xe khi đến sân','faq','Xem tiện ích và địa chỉ của chi nhánh trước khi đến. Phí gửi xe và lối vào phụ thuộc từng địa điểm; hỏi chi nhánh qua mục Hỗ trợ nếu cần hướng dẫn.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(9,'huong-dan-rally-4','Khởi động cổ tay','faq','Khởi động nhẹ cổ tay, vai và khuỷu tay trước khi vào sân. Tăng cường độ từ từ; nếu có đau hoặc chấn thương, dừng chơi và nhờ người có chuyên môn hướng dẫn.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(10,'huong-dan-rally-5','Bước di chuyển ngang','faq','Tập bước nhỏ và trở về vị trí chuẩn bị sau mỗi lần di chuyển. Chọn buổi học cùng huấn luyện viên nếu muốn được chỉnh động tác trực tiếp.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(11,'huong-dan-rally-6','Đánh đôi an toàn','faq','Thống nhất cách gọi cầu với đồng đội trước khi chơi. Giữ khoảng cách khi vung vợt và dừng pha cầu nếu có người đi vào sân.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(12,'huong-dan-rally-7','Chọn giày phù hợp','faq','Dùng giày thể thao phù hợp mặt sân trong nhà và kiểm tra độ bám trước khi chơi. Tránh giày có đế hỏng hoặc để lại vết trên mặt sân.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(13,'huong-dan-rally-8','Bảo quản vợt','faq','Lau khô vợt sau buổi chơi và cất trong túi ở nơi thoáng. Tránh để vợt trong xe nóng hoặc va chạm mạnh; kiểm tra khung và dây trước khi sử dụng.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(14,'huong-dan-rally-9','Chọn độ căng dây','faq','Độ căng dây nên phù hợp sức tay, trình độ và giới hạn của khung vợt. Trao đổi với nơi căng dây hoặc huấn luyện viên trước khi đổi mức căng.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(15,'huong-dan-rally-10','Luyện giao cầu','faq','Tập giao cầu ngắn và dài theo từng nhóm nhỏ, theo dõi độ ổn định trước khi tăng tốc độ. Huấn luyện viên có thể giúp chỉnh tư thế và điểm tiếp xúc cầu.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(16,'huong-dan-rally-11','Uống nước giữa buổi','faq','Mang theo nước và nghỉ giữa các lượt chơi. Nếu cần mua nước hoặc thuê vợt, chọn dịch vụ khi đặt sân hoặc liên hệ quầy để bổ sung vào hóa đơn.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(17,'huong-dan-rally-12','Quy tắc đổi sân','faq','Trong Lịch của tôi, mở lịch chưa thanh toán và chọn đổi lịch nếu còn đủ điều kiện. Sân mới phải cùng chi nhánh, còn trống; hệ thống tính lại giá trước khi bạn xác nhận.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(18,'huong-dan-rally-13','Thời hạn thanh toán cọc','faq','Xem số tiền cọc và thời hạn ngay trong chi tiết lịch. Lịch chưa đủ cọc sẽ bị hủy khi hết hạn; sau khi chuyển khoản, kiểm tra trạng thái xác nhận trước giờ chơi.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(19,'huong-dan-rally-14','Cách kiểm tra lịch đặt','faq','Vào Tài khoản → Lịch của tôi để lọc theo trạng thái. Mở từng lịch để xem giờ chơi, sân, khoản đã trả, hóa đơn và mã nhận sân.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(20,'huong-dan-rally-15','Tìm đồng đội cùng trình độ','faq','Vào Cộng đồng để tìm bài phù hợp khu vực, giờ chơi và trình độ. Gửi yêu cầu tham gia; chủ bài xác nhận theo số chỗ còn lại.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(21,'huong-dan-rally-16','Xem lịch sử thanh toán','faq','Mở chi tiết lịch để xem các khoản thu và hoàn. Với ví, xem sổ giao dịch trong Ví HUB; đối chiếu số tiền và thời gian trước khi gửi yêu cầu hỗ trợ.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(22,'huong-dan-rally-17','Đổi ảnh đại diện','faq','Mở Hồ sơ cá nhân, bấm ảnh đại diện rồi chọn ảnh của bạn và lưu. Dùng ảnh rõ mặt; bạn có thể xóa ảnh để trở lại biểu tượng tên viết tắt.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(23,'huong-dan-rally-18','Bảo mật tài khoản','faq','Dùng mật khẩu riêng cho website và giữ kín mã OTP. Đổi mật khẩu trong Hồ sơ cá nhân khi cần; đăng xuất sau khi dùng máy tính chung.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(24,'huong-dan-rally-19','Liên kết Google','faq','Đăng nhập tài khoản hiện tại rồi mở Hồ sơ cá nhân → Google để liên kết khi dịch vụ khả dụng. Sau đó bạn có thể dùng cùng tài khoản Google để đăng nhập nhanh.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(25,'huong-dan-rally-20','Tích điểm sau buổi chơi','faq','Điểm được cộng khi lịch sân đã hoàn tất hoặc mua hàng đủ điều kiện. Xem số dư điểm và lịch sử trong Quyền lợi & đã lưu; khoản nạp ví không tự tạo điểm mua hàng.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(26,'huong-dan-rally-21','Sử dụng ưu đãi','faq','Nhập mã voucher tại bước xác nhận đặt sân. Hệ thống kiểm tra chi nhánh, thời hạn, giá trị tối thiểu và lượt sử dụng, rồi hiển thị số tiền giảm.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(27,'huong-dan-rally-22','Đăng ký sự kiện','faq','Mở Giải đấu, chọn sự kiện còn nhận đăng ký và xem lịch, địa điểm, phí. Vé trả phí cần được thanh toán trong thời hạn để xác nhận chỗ.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(28,'huong-dan-rally-23','Chờ chỗ sự kiện','faq','Nếu sự kiện đã đủ chỗ, tham gia danh sách chờ khi có tùy chọn này. Theo dõi thông báo mời khi có suất trống và xác nhận trong thời hạn ghi trên vé.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(29,'huong-dan-rally-24','Học cùng huấn luyện viên','faq','Mở Học cầu lông, chọn huấn luyện viên và giờ còn trống. Kiểm tra chi phí sân và buổi tập trong tổng tiền trước khi xác nhận đặt.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54'),(30,'huong-dan-rally-25','Gửi phản hồi về sân','faq','Sau buổi chơi đã hoàn tất, mở lịch để đánh giá sân. Nếu cần xử lý vấn đề cụ thể, gửi phiếu trong Hỗ trợ kèm chi nhánh, mã lịch và nội dung cần hỗ trợ.',1,'2026-10-11 10:43:54','2026-10-11 10:43:54');
/*!40000 ALTER TABLE `content_pages` ENABLE KEYS */;
